import Foundation

/// The units of each kind and their factors, as converter/units.py keeps them, in its order.
public enum UnitTables: UnitTablesContract {
    static let length: [(String, Double)] = [
        ("mm", 0.001), ("cm", 0.01), ("m", 1.0), ("km", 1000.0), ("in", 0.0254), ("ft", 0.3048), ("yd", 0.9144), ("mi", 1609.344),
    ]
    static let mass: [(String, Double)] = [
        ("mg", 0.000001), ("g", 0.001), ("kg", 1.0), ("oz", 0.028349523125), ("lb", 0.45359237), ("st", 6.35029318),
    ]
    static let temperature = ["C", "F", "K"]

    public static func kind(of unit: String) throws -> String {
        if length.contains(where: { $0.0 == unit }) { return "length" }
        if mass.contains(where: { $0.0 == unit }) { return "mass" }
        if temperature.contains(unit) { return "temperature" }
        throw CoreFailure.invalid("unknown unit: \(unit). Use a length (mm cm m km in ft yd mi), a mass (mg g kg oz lb st) or C, F or K.")
    }

    public static func lengthFactor(unit: String) throws -> Double {
        guard let factor = length.first(where: { $0.0 == unit })?.1 else {
            throw CoreFailure.invalid("unknown length unit: \(unit). Use mm, cm, m, km, in, ft, yd or mi.")
        }
        return factor
    }

    public static func massFactor(unit: String) throws -> Double {
        guard let factor = mass.first(where: { $0.0 == unit })?.1 else {
            throw CoreFailure.invalid("unknown mass unit: \(unit). Use mg, g, kg, oz, lb or st.")
        }
        return factor
    }

    public static func units(kind: String) throws -> [String] {
        switch kind {
        case "length": return length.map(\.0)
        case "mass": return mass.map(\.0)
        case "temperature": return temperature
        default: throw CoreFailure.invalid("unknown kind: \(kind). Use length, mass or temperature.")
        }
    }
}
