import Foundation

/// Every conversion, the table and Python's rounding, ported from converter/length.py, mass.py, temperature.py and cli.py.
public enum Conversions: ConversionsContract {
    static let absoluteZeroC = -273.15

    public static func rounded(value: Double, places: Int) throws -> Double {
        let scale = pow(10, places)
        return (value * scale).rounded(.toNearestOrEven) / scale
    }

    public static func convertLength(value: Double, from: String, to: String) throws -> Double {
        let metres = try value * UnitTables.lengthFactor(unit: from)
        return try metres / UnitTables.lengthFactor(unit: to)
    }

    public static func convertMass(value: Double, from: String, to: String) throws -> Double {
        let kilograms = try value * UnitTables.massFactor(unit: from)
        return try kilograms / UnitTables.massFactor(unit: to)
    }

    public static func convertTemperature(value: Double, from: String, to: String) throws -> Double {
        let celsius = try toCelsius(value, from)
        if celsius < absoluteZeroC {
            throw CoreFailure.invalid("\(value) \(from) is below absolute zero: give a temperature at or above -273.15 C.")
        }
        return try fromCelsius(celsius, to)
    }

    public static func convert(value: Double, from: String, to: String) throws -> Double {
        let fromKind = try? UnitTables.kind(of: from)
        let toKind = try? UnitTables.kind(of: to)
        guard let kind = fromKind, kind == toKind else {
            throw CoreFailure.invalid("cannot convert \(from) to \(to): give two units of one kind (length, mass or temperature).")
        }
        switch kind {
        case "length": return try convertLength(value: value, from: from, to: to)
        case "mass": return try convertMass(value: value, from: from, to: to)
        default: return try convertTemperature(value: value, from: from, to: to)
        }
    }

    public static func table(from: String, to: String, start: Double, stop: Double, step: Double) throws -> [ConversionRow] {
        guard step > 0 else { throw CoreFailure.invalid("A step of \(step) never reaches the stop: give a step above zero.") }
        var rows: [ConversionRow] = []
        var value = start
        while value <= stop {
            rows.append(ConversionRow(value: value, converted: try convert(value: value, from: from, to: to)))
            value += step
        }
        return rows
    }

    static func toCelsius(_ value: Double, _ unit: String) throws -> Double {
        switch unit {
        case "C": return value
        case "F": return (value - 32) * 5 / 9
        case "K": return value - 273.15
        default: throw CoreFailure.invalid("unknown temperature unit: \(unit). Use C, F or K.")
        }
    }

    static func fromCelsius(_ value: Double, _ unit: String) throws -> Double {
        switch unit {
        case "C": return value
        case "F": return value * 9 / 5 + 32
        case "K": return value + 273.15
        default: throw CoreFailure.invalid("unknown temperature unit: \(unit). Use C, F or K.")
        }
    }
}
