import Foundation

/// `convert`: one value, converted and rounded half to even.
enum ConvertHandler: CommandHandler {
    static func run(_ arguments: ConvertArguments, _ kit: CommandKit) async throws -> [Product] {
        let places = arguments.precision ?? 4
        let raw = try Conversions.convert(value: arguments.value, from: arguments.from, to: arguments.to)
        let result = try Conversions.rounded(value: raw, places: places)
        return [
            .value("result", result, unit: arguments.to),
            .say("\(FactValue.format(arguments.value)) \(arguments.from) is \(FactValue.format(result)) \(arguments.to)."),
        ]
    }
}
