import Foundation

/// `table`: the rows as CSV, and as a report Canvas shows.
enum TableHandler: CommandHandler {
    static func run(_ arguments: TableArguments, _ kit: CommandKit) async throws -> [Product] {
        let places = arguments.precision ?? 4
        let rows = try Conversions.table(from: arguments.from, to: arguments.to, start: arguments.start, stop: arguments.stop, step: arguments.step)
        guard rows.count <= 2000 else {
            throw CoreFailure.invalid("That table has \(rows.count) rows: give a larger step, for 2000 rows at most.")
        }
        let cells = try rows.map { row in
            [FactValue.format(row.value), FactValue.format(try Conversions.rounded(value: row.converted, places: places))]
        }
        let columns = [arguments.from, arguments.to]
        let report = Report(name: "table", title: "\(arguments.from) to \(arguments.to)",
                            subtitle: "From \(FactValue.format(arguments.start)) to \(FactValue.format(arguments.stop)) in steps of \(FactValue.format(arguments.step))",
                            blocks: [.table(columns: columns, rows: cells)])
        return [
            .value("rows", rows.count),
            .csv("table", columns: columns, rows: cells),
            .report(report),
            .say("\(rows.count) rows from \(arguments.from) to \(arguments.to)."),
        ]
    }
}
