import Foundation

/// `units`: each unit of a kind with its factor in the kind's base unit.
enum UnitsHandler: CommandHandler {
    static func run(_ arguments: UnitsArguments, _ kit: CommandKit) async throws -> [Product] {
        let kinds = arguments.kind.map { [$0] } ?? ["length", "mass", "temperature"]
        var rows: [[String]] = []
        for kind in kinds {
            for unit in try UnitTables.units(kind: kind) {
                switch kind {
                case "length": rows.append([kind, unit, FactValue.format(try UnitTables.lengthFactor(unit: unit)) + " m"])
                case "mass": rows.append([kind, unit, FactValue.format(try UnitTables.massFactor(unit: unit)) + " kg"])
                default: rows.append([kind, unit, "a scale of its own"])
                }
            }
        }
        return [
            .value("count", rows.count),
            .csv("units", columns: ["kind", "unit", "in its base unit"], rows: rows),
            .say("\(rows.count) units of \(kinds.joined(separator: ", "))."),
        ]
    }
}
